const scraped = $input.first();
const templateMeta = $('Process Each Template').item.json;

let html = scraped.json?.data?.html || scraped.json?.html || '';

if (!html || html.length < 500) {
  // Fallback: use a minimal placeholder with the template description
  html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>{{brand_name}}</title>
<style>
  body { font-family: Inter, sans-serif; margin: 0; background: #0a0a0f; color: #f8fafc; }
  .hero { min-height: 100vh; display: flex; align-items: center; justify-content: center; text-align: center; padding: 2rem; background: linear-gradient(135deg, #1e1b4b, #0a0a0f); }
  h1 { font-size: clamp(2rem, 6vw, 5rem); margin-bottom: 1rem; }
  p { font-size: 1.25rem; opacity: 0.7; margin-bottom: 2rem; }
  .btn { padding: 1rem 2.5rem; background: {{primary_color}}; color: white; border: none; border-radius: 8px; font-size: 1rem; font-weight: 600; cursor: pointer; text-decoration: none; display: inline-block; }
  footer { padding: 2rem; text-align: center; opacity: 0.4; font-size: 0.875rem; }
</style>
</head>
<body>
<section class="hero">
  <div>
    <h1>{{hero_headline}}</h1>
    <p>{{hero_subtext}}</p>
    <a href="#" class="btn">{{cta_text}}</a>
  </div>
</section>
<footer>{{footer_text}}</footer>
</body>
</html>`;
}

// Add {{tokens}} to the scraped HTML
const title = templateMeta.name;
const sourceUrl = templateMeta.demo_url;

// Basic tokenization — replace the first h1 text with hero_headline token
html = html
  .replace(/<title>[^<]*<\/title>/, '<title>{{brand_name}}</title>')
  .replace(/<!-- Source: [^>]* -->\n?/, '')
  + `\n<!-- Sourced from: ${sourceUrl} | License: Creative Commons Attribution 3.0 -->`;

return [{
  json: {
    name: templateMeta.name,
    category: templateMeta.category,
    theme: templateMeta.theme,
    color_scheme: templateMeta.color_scheme,
    description: templateMeta.description,
    source_url: sourceUrl,
    template_html: html,
    is_public: true,
    usage_count: 0
  }
}];

const result = $input.first();
const success = result.json?.id || result.json?.name;
const name = $('Process + Tokenize HTML').item.json.name;

if (success) {
  console.log(`✅ Created: "${name}" — ID: ${result.json.id}`);
} else {
  console.log(`❌ Failed: "${name}" — ${JSON.stringify(result.json)}`);
}
return $input.all();
